# EVOLVE-BLOCK-START
import pandas as pd
import numpy as np
from solver import Algorithm
from typing import Tuple, List
from collections import defaultdict


class Evolved(Algorithm):
    """
    Character-trie prefix caching optimizer (v5).

    Total trie reuse over a fixed multiset of serialized row strings is
    insertion-order independent, so only per-row column orderings matter.
    Build a bounded set of cheap candidate orderings, score each exactly
    with the sorted-string adjacent-LCP sum, and return the best:
      (a) global order ranked by sum(len(v)*cnt*(cnt-1)),
      (b) global order ranked by prefix savings sum(len(v)*(cnt-1)),
      (c) conditional partition tree, length-weighted pair repetition,
          with *local* leaf tail ordering by within-group repetition,
      (d) same tree with global tail ordering (deterministic cheap tail),
      (e) greedy sequential order driven by the real LCP objective,
          plus a bounded adjacent-swap refinement,
      (f) the original column order (floor).
    """

    def __init__(self, df: pd.DataFrame = None):
        self.df = df

    # ---------- serialization ----------

    @staticmethod
    def _cell_str(v) -> str:
        """Scoring serialization: missing -> '', else str(v)."""
        if v is None:
            return ""
        if isinstance(v, float) and v != v:
            return ""
        return str(v)

    def _serialize_matrix(self, df: pd.DataFrame):
        """Raw object matrix (cells preserved exactly) + cell-string matrix."""
        raw = df.to_numpy(dtype=object)
        ser = [[self._cell_str(v) for v in row] for row in raw]
        return raw, ser

    # ---------- scoring ----------

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """LCP via binary search on prefix slices (C-speed comparisons)."""
        if a == b:
            return len(a)
        hi = min(len(a), len(b))
        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    def _score(self, strings: List[str]) -> int:
        """Exact ideal trie reuse: sum of adjacent LCPs after sorting."""
        if len(strings) < 2:
            return 0
        ss = sorted(strings)
        total = 0
        prev = ss[0]
        for i in range(1, len(ss)):
            cur = ss[i]
            total += self._lcp(prev, cur)
            prev = cur
        return total

    @staticmethod
    def _build_strings(ser, order_matrix) -> List[str]:
        return ["".join([row[c] for c in o]) for row, o in zip(ser, order_matrix)]

    # ---------- statistics ----------

    @staticmethod
    def _col_counts(ser, m: int):
        """Per-column {serialized value: count}, one pass per column."""
        return [
            (lambda d: ([d.__setitem__(row[c], d.get(row[c], 0) + 1) for row in ser], d)[1])({})
            for c in range(m)
        ]

    # ---------- candidates ----------

    def _global_orders(self, counts, m: int):
        """Two global rankings: pair-repetition weighted and prefix-savings."""
        pair = [0] * m
        pref = [0] * m
        for c in range(m):
            p = q = 0
            for v, k in counts[c].items():
                if k > 1:
                    p += len(v) * k * (k - 1)
                    q += len(v) * (k - 1)
            pair[c], pref[c] = p, q
        g_order = sorted(range(m), key=lambda c: (-pair[c], c))
        p_order = sorted(range(m), key=lambda c: (-pref[c], c))
        return g_order, p_order

    def _tree_orders(self, ser, tail_order, m: int, weighted: bool,
                     local_tail: bool, max_depth=8, max_cands=24):
        """Conditional partition tree.

        Inside each row group, pick a remaining field by pair repetition
        (len-weighted or not), partition rows by that field's value, and
        recurse per group. Leaves get either a locally computed tail order
        (by within-group repetition) or the global tail order.
        """
        n = len(ser)
        tail = list(tail_order)

        def leaf_order(row_ids, used):
            rem = [c for c in tail if c not in used]
            if not local_tail or len(row_ids) < 2 or not rem:
                return rem
            scored = []
            for c in rem:
                cnts = defaultdict(int)
                for i in row_ids:
                    cnts[ser[i][c]] += 1
                s = 0
                for v, k in cnts.items():
                    if k > 1:
                        s += len(v) * k * (k - 1) if weighted else k * (k - 1)
                scored.append((-s, c))
            scored.sort()
            return [c for _, c in scored]

        def rec(row_ids, used, depth):
            if len(row_ids) < 2 or depth >= max_depth or len(used) >= m:
                rem = leaf_order(row_ids, used)
                return {i: rem for i in row_ids}
            cands = [c for c in tail if c not in used][:max_cands]
            best_col, best_gain = None, 0
            for c in cands:
                cnts = defaultdict(int)
                for i in row_ids:
                    cnts[ser[i][c]] += 1
                gain = 0
                for v, k in cnts.items():
                    if k > 1:
                        gain += len(v) * k * (k - 1) if weighted else k * (k - 1)
                if gain > best_gain:
                    best_gain, best_col = gain, c
            if best_col is None:
                rem = leaf_order(row_ids, used)
                return {i: rem for i in row_ids}
            groups = defaultdict(list)
            for i in row_ids:
                groups[ser[i][best_col]].append(i)
            result = {}
            new_used = used | {best_col}
            for g in groups.values():
                for i, suffix in rec(g, new_used, depth + 1).items():
                    result[i] = [best_col] + suffix
            return result

        res = rec(list(range(n)), set(), 0)
        return [res.get(i) or list(tail) for i in range(n)]

    def _greedy_order(self, ser, m: int, n: int) -> List[int]:
        """Greedy sequential order driven by the real LCP objective."""
        order = []
        remaining = set(range(m))
        partial = [""] * n
        for _ in range(m):
            best_col, best_s = None, -1
            for c in remaining:
                s = self._score([p + row[c] for p, row in zip(partial, ser)])
                if s > best_s:
                    best_s, best_col = s, c
            order.append(best_col)
            remaining.discard(best_col)
            partial = [p + row[best_col] for p, row in zip(partial, ser)]
        return order

    def _swap_refine(self, ser, order, m: int, n: int) -> List[int]:
        """One bounded pass of adjacent swaps, accepted only on real LCP gain."""
        order = list(order)
        base = self._score(self._build_strings(ser, [order] * n))
        i = 0
        while i < m - 1:
            cand = list(order)
            cand[i], cand[i + 1] = cand[i + 1], cand[i]
            s = self._score(self._build_strings(ser, [cand] * n))
            if s > base:
                order, base = cand, s
                i = max(0, i - 1)
            else:
                i += 1
        return order

    # ---------- main API ----------

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop=None,
        col_stop=None,
        col_merge: List[List[str]] = [],
        one_way_dep=[],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        initial_df = df.copy()

        if col_merge:
            try:
                _, stats = self.calculate_col_stats(df, enable_index=True)
                reordered_columns = [c for c, _, _, _ in stats]
                for grp in col_merge:
                    final_order = [c for c in reordered_columns if c in grp]
                    if len(final_order) > 1:
                        df = self.merging_columns(df, final_order, prepended=False)
            except Exception:
                pass

        colnames = list(df.columns)
        n, m = df.shape
        if n == 0 or m == 0:
            return df.copy(), [list(colnames) for _ in range(n)]
        if m == 1 or n == 1:
            out_df = pd.DataFrame(df.to_numpy(dtype=object), columns=colnames)
            return out_df, [list(colnames) for _ in range(n)]

        raw, ser = self._serialize_matrix(df)
        counts = self._col_counts(ser, m)

        # Two distinct global rankings (pair repetition vs prefix savings)
        g_order, p_order = self._global_orders(counts, m)

        cands = [[g_order] * n]
        if p_order != g_order:
            cands.append([p_order] * n)

        depth = min(8, col_stop if isinstance(col_stop, int) else 8)
        # Tree with local leaf tails (per-group adaptive suffix ordering)
        try:
            cands.append(self._tree_orders(ser, g_order, m, True, True, max_depth=depth))
        except Exception:
            pass
        # Trees with deterministic global tail
        try:
            cands.append(self._tree_orders(ser, g_order, m, True, False, max_depth=depth))
        except Exception:
            pass
        try:
            cands.append(self._tree_orders(ser, g_order, m, False, False, max_depth=depth))
        except Exception:
            pass

        # Greedy sequential order driven by the real LCP score + bounded swaps
        if n > 1 and n * m * m <= 4_000_000:
            try:
                greedy = self._greedy_order(ser, m, n)
                cands.append([greedy] * n)
                if m > 2 and n * m <= 500_000:
                    refined = self._swap_refine(ser, greedy, m, n)
                    if refined != greedy:
                        cands.append([refined] * n)
            except Exception:
                pass

        # Original column order (floor)
        cands.append([list(range(m))] * n)

        best_score, best_orders = -1, cands[0]
        for orders in cands:
            try:
                s = self._score(self._build_strings(ser, orders))
            except Exception:
                continue
            if s > best_score:
                best_score, best_orders = s, orders

        out = np.empty((n, m), dtype=object)
        for i in range(n):
            row_raw = raw[i]
            out[i] = [row_raw[c] for c in best_orders[i]]

        out_df = pd.DataFrame(out, columns=colnames)
        column_orderings = [[colnames[c] for c in o] for o in best_orders]

        if not col_merge:
            assert out_df.shape == initial_df.shape
        else:
            assert out_df.shape[0] == initial_df.shape[0]
        return out_df, column_orderings

